{"path":"neuron_growth_ollama-ornith-35b_01.html","content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Neural Network Growth Simulation</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #05070f;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    overflow: hidden;
  }
  canvas {
    display: block;
    border: 1px solid rgba(0, 229, 255, 0.15);
    border-radius: 4px;
  }
</style>
</head>
<body>
<canvas id="canvas" width="800" height="800"></canvas>
<script src="https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js"></script>
<script>
// === CONFIGURATION ===
const params = {
  // Growth
  neuronCount: 4,
  branchGrowthSpeed: 3,
  maxBranchDepth: 6,
  branchSplitChance: 0.3,
  branchCurvature: 0.4,
  maxBranchLength: 180,
  // Synapses
  synapseDistanceThreshold: 60,
  synapseGlowStrength: 8,
  // Pulses
  pulseSpeed: 2.5,
  pulseFrequency: 0.02,
  pulseBrightness: 1.0,
  // Visuals
  backgroundColor: '#05070f',
  branchColor: '#00e5ff',
  accentBranchColor: '#d6ff00',
  synapseColor: '#ff2bd6',
  pulseColor: '#fff36a',
  // Buttons
  regenerateNetwork: function() { regenerate(); },
  clearCanvas: function() { ctx.clearRect(0, 0, canvas.width, canvas.height); },
  pauseResume: function() { paused = !paused; }
};

// === STATE ===
let canvas, ctx;
let branches = [];
let synapses = [];
let pulses = [];
let paused = false;
let time = 0;
let networkComplete = false;

// === SETUP ===
function init() {
  canvas = document.getElementById('canvas');
  ctx = canvas.getContext('2d');
  setupGUI();
  regenerate();
  animate();
}

function setupGUI() {
  const gui = new dat.GUI({ width: 320 });

  const growthFolder = gui.addFolder('Growth');
  growthFolder.add(params, 'neuronCount', 3, 6, 1).name('Neuron Count');
  growthFolder.add(params, 'branchGrowthSpeed', 1, 8, 0.5).name('Growth Speed');
  growthFolder.add(params, 'maxBranchDepth', 3, 10, 1).name('Max Depth');
  growthFolder.add(params, 'branchSplitChance', 0, 1, 0.05).name('Split Chance');
  growthFolder.add(params, 'branchCurvature', 0, 1, 0.05).name('Curvature');
  growthFolder.add(params, 'maxBranchLength', 80, 300, 10).name('Max Length');
  growthFolder.open();

  const synFolder = gui.addFolder('Synapses');
  synFolder.add(params, 'synapseDistanceThreshold', 20, 120, 5).name('Distance Threshold');
  synFolder.add(params, 'synapseGlowStrength', 2, 20, 1).name('Glow Strength');
  synFolder.open();

  const pulseFolder = gui.addFolder('Pulses');
  pulseFolder.add(params, 'pulseSpeed', 0.5, 6, 0.1).name('Pulse Speed');
  pulseFolder.add(params, 'pulseFrequency', 0.005, 0.05, 0.005).name('Frequency');
  pulseFolder.add(params, 'pulseBrightness', 0.3, 2.0, 0.1).name('Brightness');
  pulseFolder.open();

  const visualFolder = gui.addFolder('Visuals');
  visualFolder.addColor(params, 'backgroundColor').name('Background Color');
  visualFolder.addColor(params, 'branchColor').name('Branch Color');
  visualFolder.addColor(params, 'accentBranchColor').name('Accent Color');
  visualFolder.addColor(params, 'synapseColor').name('Synapse Color');
  visualFolder.addColor(params, 'pulseColor').name('Pulse Color');
  visualFolder.open();

  gui.add(params, 'regenerateNetwork').name('Regenerate Network');
  gui.add(params, 'clearCanvas').name('Clear Canvas');
  gui.add(params, 'pauseResume').name('Pause / Resume');
}

// === NEURON GROWTH ===
function regenerate() {
  branches = [];
  synapses = [];
  pulses = [];
  networkComplete = false;
  time = 0;

  const cx = canvas.width / 2;
  const cy = canvas.height / 2;
  const count = params.neuronCount;

  for (let i = 0; i < count; i++) {
    const offsetX = (Math.random() - 0.5) * 200;
    const offsetY = (Math.random() - 0.5) * 200;
    const seed = {
      x: cx + offsetX,
      y: cy + offsetY,
      angle: Math.random() * Math.PI * 2,
      depth: 0,
      length: 0,
      thickness: 1.5 + Math.random() * 1.5,
      isAccent: Math.random() > 0.7,
      children: [],
      tipX: cx + offsetX,
      tipY: cy + offsetY,
      growing: true
    };
    branches.push(seed);
  }
}

function growBranch(branch, angleOffset) {
  if (!branch.growing || branch.depth >= params.maxBranchDepth) {
    branch.growing = false;
    return;
  }

  const speed = params.branchGrowthSpeed;
  const curv = (Math.random() - 0.5) * params.branchCurvature;
  const newAngle = branch.angle + angleOffset + curv;
  const stepLen = speed * (1 + branch.depth * 0.2);

  const startX = branch.tipX;
  const startY = branch.tipY;
  const endX = startX + Math.cos(newAngle) * stepLen;
  const endY = startY + Math.sin(newAngle) * stepLen;

  branch.tipX = endX;
  branch.tipY = endY;
  branch.length += stepLen;

  if (branch.length >= params.maxBranchLength) {
    branch.growing = false;
    return;
  }

  // Occasionally spawn a side branch
  if (Math.random() < params.branchSplitChance && branch.depth < params.maxBranchDepth - 1) {
    const sideAngle = newAngle + (Math.random() > 0.5 ? 1 : -1) * (Math.PI / 4 + Math.random() * 0.5);
    const child = {
      x: startX,
      y: startY,
      angle: sideAngle,
      depth: branch.depth + 1,
      length: 0,
      thickness: branch.thickness * (0.4 + Math.random() * 0.4),
      isAccent: branch.isAccent || Math.random() > 0.6,
      children: [],
      tipX: startX,
      tipY: startY,
      growing: true
    };
    branch.children.push(child);
    branches.push(child);
  }
}

function checkSynapses() {
  const threshold = params.synapseDistanceThreshold;
  const thresholdSq = threshold * threshold;

  for (let i = 0; i < branches.length; i++) {
    for (let j = i + 1; j < branches.length; j++) {
      const a = branches[i];
      const b = branches[j];
      if (!a.growing && !b.growing) continue;

      const dx = a.tipX - b.tipX;
      const dy = a.tipY - b.tipY;
      const distSq = dx * dx + dy * dy;

      if (distSq < thresholdSq) {
        const key = Math.min(i, j) + ',' + Math.max(i, j);
        if (!synapses.find(s => s.key === key)) {
          synapses.push({
            key: key,
            from: i,
            to: j,
            alpha: 0,
            pulsePhase: Math.random() * Math.PI * 2
          });
        }
      }
    }
  }
}

function spawnPulse() {
  if (synapses.length === 0) return;
  if (Math.random() > params.pulseFrequency) return;

  const syn = synapses[Math.floor(Math.random() * synapses.length)];
  const fromIdx = syn.from;
  const toIdx = syn.to;
  const fromBranch = branches[fromIdx];
  const toBranch = branches[toIdx];

  pulses.push({
    fromX: fromBranch.tipX,
    fromY: fromBranch.tipY,
    toX: toBranch.tipX,
    toY: toBranch.tipY,
    t: 0,
    speed: params.pulseSpeed * (0.8 + Math.random() * 0.4),
    size: 2 + Math.random() * 2,
    brightness: params.pulseBrightness
  });
}

// === RENDERING ===
function drawBackground() {
  ctx.fillStyle = params.backgroundColor;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Subtle grid
  ctx.strokeStyle = 'rgba(0, 229, 255, 0.04)';
  ctx.lineWidth = 0.5;
  const gridSize = 40;
  for (let x = 0; x < canvas.width; x += gridSize) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, canvas.height);
    ctx.stroke();
  }
  for (let y = 0; y < canvas.height; y += gridSize) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(canvas.width, y);
    ctx.stroke();
  }

  // Scanlines
  ctx.fillStyle = 'rgba(0, 229, 255, 0.015)';
  for (let y = 0; y < canvas.height; y += 3) {
    ctx.fillRect(0, y, canvas.width, 1);
  }

  // Vignette
  const gradient = ctx.createRadialGradient(400, 400, 100, 400, 400, 500);
  gradient.addColorStop(0, 'transparent');
  gradient.addColorStop(1, 'rgba(0, 0, 0, 0.45)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

function drawBranch(branch) {
  if (branch.depth === 0) return; // Skip root

  const color = branch.isAccent ? params.accentBranchColor : params.branchColor;
  const thickness = branch.thickness;

  ctx.save();
  ctx.shadowColor = color;
  ctx.shadowBlur = 6;
  ctx.strokeStyle = color;
  ctx.lineWidth = thickness;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  ctx.beginPath();
  ctx.moveTo(branch.x, branch.y);
  ctx.quadraticCurveTo(
    (branch.x + branch.tipX) / 2 + (Math.random() - 0.5) * 4,
    (branch.y + branch.tipY) / 2 + (Math.random() - 0.5) * 4,
    branch.tipX,
    branch.tipY
  );
  ctx.stroke();
  ctx.restore();

  // Draw children
  for (const child of branch.children) {
    drawBranch(child);
  }
}

function drawSynapses() {
  for (const syn of synapses) {
    const from = branches[syn.from];
    const to = branches[syn.to];
    if (!from || !to) continue;

    syn.alpha = Math.min(1, syn.alpha + 0.02);
    const pulse = 0.6 + 0.4 * Math.sin(time * 0.03 + syn.pulsePhase);
    const alpha = syn.alpha * pulse;

    ctx.save();
    ctx.shadowColor = params.synapseColor;
    ctx.shadowBlur = params.synapseGlowStrength * pulse;
    ctx.strokeStyle = params.synapseColor;
    ctx.globalAlpha = alpha * 0.7;
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 4]);

    ctx.beginPath();
    ctx.moveTo(from.tipX, from.tipY);
    ctx.lineTo(to.tipX, to.tipY);
    ctx.stroke();

    // Connection node
    const midX = (from.tipX + to.tipX) / 2;
    const midY = (from.tipY + to.tipY) / 2;
    ctx.setLineDash([]);
    ctx.globalAlpha = alpha;
    ctx.fillStyle = params.synapseColor;
    ctx.beginPath();
    ctx.arc(midX, midY, 2.5 * pulse, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }
}

function drawPulses() {
  for (let i = pulses.length - 1; i >= 0; i--) {
    const p = pulses[i];
    p.t += 0.01 * p.speed;

    if (p.t > 1) {
      pulses.splice(i, 1);
      continue;
    }

    const x = p.fromX + (p.toX - p.fromX) * p.t;
    const y = p.fromY + (p.toY - p.fromY) * p.t;

    ctx.save();
    ctx.shadowColor = params.pulseColor;
    ctx.shadowBlur = 12 * p.brightness;
    ctx.fillStyle = params.pulseColor;
    ctx.globalAlpha = p.brightness;

    // Spark core
    ctx.beginPath();
    ctx.arc(x, y, p.size, 0, Math.PI * 2);
    ctx.fill();

    // Trail
    const trailLen = 5;
    const grad = ctx.createRadialGradient(x, y, 0, x, y, p.size * trailLen);
    grad.addColorStop(0, params.pulseColor);
    grad.addColorStop(1, 'transparent');
    ctx.globalAlpha = 0.4 * p.brightness;
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, p.size * trailLen, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }
}

function drawNeuronCores() {
  for (let i = 0; i < branches.length; i++) {
    const b = branches[i];
    if (b.depth !== 0) continue;

    const pulse = 0.7 + 0.3 * Math.sin(time * 0.02 + i);
    ctx.save();
    ctx.shadowColor = params.branchColor;
    ctx.shadowBlur = 15 * pulse;
    ctx.fillStyle = params.branchColor;
    ctx.globalAlpha = pulse;
    ctx.beginPath();
    ctx.arc(b.x, b.y, 4 + 2 * pulse, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
}

// === ANIMATION LOOP ===
function animate() {
  requestAnimationFrame(animate);
  if (paused) return;

  time++;

  // Grow branches
  let allDone = true;
  for (const branch of branches) {
    if (branch.growing) {
      growBranch(branch, 0);
      for (const child of branch.children) {
        if (child.growing) {
          growBranch(child, (Math.random() - 0.5) * 0.3);
        }
      }
      allDone = false;
    }
  }

  if (allDone && !networkComplete) {
    networkComplete = true;
  }

  // Check synapses
  if (!networkComplete) {
    checkSynapses();
  }

  // Spawn pulses
  if (networkComplete) {
    spawnPulse();
  }

  // Render
  drawBackground();
  drawBranches();
  drawSynapses();
  drawPulses();
  drawNeuronCores();
}

function drawBranches() {
  for (const branch of branches) {
    drawBranch(branch);
  }
}

// === INIT ===
init();
</script>
</body>
</html>
